import * as T from 'three';
export class Effects {
 constructor(scene){this.particles=Array.from({length:240},()=>({life:0,p:new T.Vector3(),v:new T.Vector3(),s:.04}));this.mesh=new T.InstancedMesh(new T.BoxGeometry(1,1,1),new T.MeshBasicMaterial({toneMapped:false}),240);this.mesh.instanceMatrix.setUsage(T.DynamicDrawUsage);this.mesh.frustumCulled=false;scene.add(this.mesh);this.dummy=new T.Object3D();this.color=new T.Color();this.cursor=0;this.lines=[];this.scene=scene;for(let i=0;i<240;i++){this.dummy.scale.setScalar(0);this.dummy.updateMatrix();this.mesh.setMatrixAt(i,this.dummy.matrix);this.mesh.setColorAt(i,new T.Color(0xffbe6b));}}
 emit(pos,n=12,color=0xffb86b,speed=3,chunk=false){for(let k=0;k<n;k++){const i=this.cursor++%240,p=this.particles[i];p.life=.3+Math.random()*(chunk?1.7:.5);p.p.copy(pos);p.v.set((Math.random()-.5)*speed,Math.random()*speed,(Math.random()-.5)*speed);p.s=chunk?.05+Math.random()*.1:.012+Math.random()*.022;this.color.setHex(color);this.mesh.setColorAt(i,this.color);}this.mesh.instanceColor.needsUpdate=true;}
 tracer(from,to,color=0xf5d99d,life=.055){const g=new T.BufferGeometry().setFromPoints([from,to]),m=new T.LineBasicMaterial({color,transparent:true,opacity:.75,depthWrite:false}),o=new T.Line(g,m);this.scene.add(o);this.lines.push({o,life,max:life});}
 update(dt){for(let i=0;i<240;i++){const p=this.particles[i];p.life-=dt;if(p.life>0){p.v.y-=dt*7;p.p.addScaledVector(p.v,dt);if(p.p.y<.035){p.p.y=.035;p.v.y=Math.abs(p.v.y)*.3;p.v.x*=.75;p.v.z*=.75;}this.dummy.position.copy(p.p);this.dummy.rotation.x+=.12;this.dummy.rotation.z+=.1;this.dummy.scale.setScalar(p.s*Math.min(1,p.life*6));}else this.dummy.scale.setScalar(0);this.dummy.updateMatrix();this.mesh.setMatrixAt(i,this.dummy.matrix);}this.mesh.instanceMatrix.needsUpdate=true;for(let i=this.lines.length-1;i>=0;i--){const p=this.lines[i];p.life-=dt;if(p.life<=0){p.o.removeFromParent();p.o.geometry.dispose();p.o.material.dispose();this.lines.splice(i,1);}else p.o.material.opacity=p.life/p.max*.75;}}
 clear(){for(const p of this.particles)p.life=0;for(const l of this.lines){l.o.removeFromParent();l.o.geometry.dispose();l.o.material.dispose();}this.lines=[];this.update(0);}
}
